// Extraction sans LLM : motif sur la reference de facture,
// adresse courriel de l'expediteur, corps du message tel quel.
//
// Un echec d'extraction n'est pas une erreur : le run part sur
// insufficient_information, qui est deja un cas gere par l'API.
// C'est un chemin d'erreur gratuit, et un appel probabiliste de moins.

const body = $input.first().json.body ?? $input.first().json;
const text = String(body.message ?? body.text ?? '');

const invoice = text.match(/\binv[_-]?([A-Za-z0-9]{3,})\b/i);
const email =
  body.customer_email ??
  body.from ??
  (text.match(/[\w.+-]+@[\w-]+\.[\w.]+/) || [null])[0];

return [{
  json: {
    message: text,
    customer_email: email,
    invoice_id: invoice ? invoice[0].replace('-', '_') : null,
    extraction_ok: Boolean(email)
  }
}];

